import { createPublicClient, http } from 'viem';
import { base } from 'viem/chains';

async function testSimulate() {
  const client = createPublicClient({ chain: base, transport: http('https://mainnet.base.org') });
  try {
    const res = await client.call({
      account: '0x9dC0a2E92cC1f08050D2c5F560A45229CcF47C98',
      to: '0x70315019d12a11556c837970675cdc8fa54d186b',
      data: ''
    });
    console.log('Call success:', res);
  } catch (err: any) {
    console.error('Simulate error message:', err.message);
    if (err.data) console.error('Simulate error data:', err.data);
    if (err.cause) console.error('Simulate error cause:', err.cause);
  }
}
testSimulate();
